const input = $input.first().json;

// Webhook body ou test manuel
const body = input.body || input;

const type = body.type || 'express';
const sujetTexte = body.sujet_texte || body.titre || body.message || '';
const notes = body.notes || '';
const sujetManuelId = body.sujet_manuel_id || '';

return [{
  json: {
    type,
    sujet_texte: sujetTexte,
    notes,
    sujet_manuel_id: sujetManuelId
  }
}];

// Détecter quel chemin a été emprunté
let request = null;
try {
  request = $('🔄 Préparer Requête').first().json;
} catch(e) {
  request = null;
}

let titre = '';
let notes = '';
let sujetManuelId = '';
let source = 'demande';

if (request && request.type === 'manuel') {
  // Mode webhook + sujet manuel
  let manuelData = null;
  try {
    manuelData = $('📋 Lire Sujet Manuel').first().json;
    if (!manuelData || !manuelData.titre) manuelData = null;
  } catch(e) { manuelData = null; }

  if (manuelData && manuelData.titre) {
    titre = manuelData.titre;
    notes = manuelData.notes || '';
    sujetManuelId = manuelData.id || '';
    source = 'manuel';
  } else {
    throw new Error('Sujet manuel non trouv\u00e9');
  }
} else if (request && request.type === 'express') {
  // Mode webhook + texte libre
  titre = request.sujet_texte;
  notes = request.notes || '';
  source = 'demande';
  if (!titre) throw new Error('sujet_texte requis en mode express');
} else {
  // Mode test manuel : lire le premier sujet dispo
  let fallback = null;
  try {
    fallback = $('🔍 Lire Premier Sujet Dispo').first().json;
  } catch(e) { fallback = null; }

  // Ou l'input direct
  if (!fallback || !fallback.titre) {
    fallback = $input.first().json;
  }

  if (fallback && fallback.titre) {
    titre = fallback.titre;
    notes = fallback.notes || '';
    sujetManuelId = fallback.id || '';
    source = 'manuel';
  } else {
    throw new Error('Aucun sujet trouv\u00e9');
  }
}

return [{
  json: {
    titre,
    notes,
    sujet_manuel_id: sujetManuelId,
    source
  }
}];

function extractAnthropicText(json) {
  if (json.text && typeof json.text === 'string' && json.text.trim().length > 0) return json.text;
  if (Array.isArray(json.content)) {
    const block = json.content.find(b => b.type === 'text' && b.text);
    if (block) return block.text;
  }
  if (typeof json.content === 'string' && json.content.trim().length > 0) return json.content;
  if (json.message && json.message.content) {
    if (Array.isArray(json.message.content)) {
      const block = json.message.content.find(b => b.type === 'text' && b.text);
      if (block) return block.text;
    }
    if (typeof json.message.content === 'string') return json.message.content;
  }
  return JSON.stringify(json);
}

const input = $input.first().json;

let context = null;
try { context = $('⚙️ Normaliser Sujet').first().json; } catch(e) { context = { source: 'demande', sujet_manuel_id: '' }; }

let responseText = extractAnthropicText(input);
responseText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let data;
try {
  data = JSON.parse(responseText);
} catch(e) {
  const m = responseText.match(/\{[\s\S]*\}/);
  if (m) data = JSON.parse(m[0]);
  else throw new Error('Parse error: ' + responseText.substring(0, 300));
}

// Calculer semaine ISO
const now = new Date();
const oneJan = new Date(now.getFullYear(), 0, 1);
const dayOfYear = Math.floor((now - oneJan) / 86400000) + 1;
const weekNum = Math.ceil((dayOfYear + oneJan.getDay()) / 7);
const semaine = now.getFullYear() + '-W' + String(weekNum).padStart(2, '0');

return [{
  json: {
    titre: data.titre,
    description: data.description,
    angle: data.angle,
    type_ressource: data.type_ressource || 'notion',
    nom_ressource: data.nom_ressource,
    desc_ressource: data.desc_ressource,
    mot_cle_cta: (data.mot_cle_cta || 'RESSOURCE').toUpperCase(),
    score_engagement: Math.min(10, Math.max(1, data.score_engagement || 7)),
    source: context.source || 'demande',
    statut: 'validee',
    semaine
  }
}];
